/**
 * @brief PKCS#8 encrypted private key container used with PEM reading/writing.
 */
typedef struct private_key_st {
    /** PKCS#8 version number for the encrypted private key container. */
    int version;
    /* The PKCS#8 data types */
    /** AlgorithmIdentifier for the encrypted private key in @c enc_pkey. */
    X509_ALGOR *enc_algor;
    /** Encrypted private-key octets (PKCS#8 encrypted content). */
    ASN1_OCTET_STRING *enc_pkey; /* encrypted pub key */
    /** Decrypted private key corresponding to @c enc_pkey when available. */
    EVP_PKEY *dec_pkey;
    /* used to encrypt and decrypt */
    /** Length in bytes of the symmetric key held in @c key_data. */
    int key_length;
    /** Symmetric key bytes of length @c key_length used to encrypt/decrypt @c enc_pkey. */
    char *key_data;
    /** Non-zero when @c key_data was allocated and should be freed with the structure. */
    int key_free; /* true if we should auto free key_data */
    /* expanded version of 'enc_algor' */
    /** Symmetric cipher parameters used to encrypt/decrypt @c key_data. */
    EVP_CIPHER_INFO cipher;
} X509_PKEY;

/**
 * @brief Bundle of certificate, CRL, and/or encrypted private key as found in PEM info files.
 */
typedef struct X509_info_st {
    /** Certificate contained in this info entry, or NULL. */
    X509 *x509;
    /** CRL contained in this info entry, or NULL. */
    X509_CRL *crl;
    /** Encrypted private key material associated with this PEM info bundle. */
    X509_PKEY *x_pkey;
    /** Cipher algorithm/parameters used when @c enc_data holds an encrypted private key. */
    EVP_CIPHER_INFO enc_cipher;
    /** Length in bytes of the encrypted private-key material at @c enc_data. */
    int enc_len;
    /** Encrypted private-key bytes of length @c enc_len, or NULL. */
    char *enc_data;
} X509_INFO;
