#define X509_extract_key(x) X509_get_pubkey(x)
/**
 * Compatibility alias for X509_REQ_get_pubkey().
 * @param a Certificate request whose public key is returned.
 */
#define X509_REQ_extract_key(a) X509_REQ_get_pubkey(a)
#define X509_name_cmp(a, b) X509_NAME_cmp((a), (b))

/**
 * @brief Install the default custom CRL method used when looking up revoked entries.
 * @param meth CRL method table to use as the process-wide default, or NULL to clear.
 */
void X509_CRL_set_default_method(const X509_CRL_METHOD *meth);
/**
 * @brief Allocate a custom CRL method with optional init, free, lookup, and verify callbacks.
 * @param crl_init Optional per-CRL initialization callback, or NULL.
 * @param crl_free Optional per-CRL cleanup callback, or NULL.
 * @param crl_lookup Optional revoked-entry lookup by serial/issuer, or NULL.
 * @param crl_verify Optional CRL signature verification callback, or NULL.
 * @return New X509_CRL_METHOD, or NULL on allocation failure; free with X509_CRL_METHOD_free.
 */
X509_CRL_METHOD *X509_CRL_METHOD_new(int (*crl_init)(X509_CRL *crl),
    int (*crl_free)(X509_CRL *crl),
    int (*crl_lookup)(X509_CRL *crl,
        X509_REVOKED **ret,
        const ASN1_INTEGER *serial,
        const X509_NAME *issuer),
    int (*crl_verify)(X509_CRL *crl,
        EVP_PKEY *pk));
/**
 * @brief Free a custom CRL method allocated by X509_CRL_METHOD_new().
 * @param m Method to free, or NULL.
 */
void X509_CRL_METHOD_free(X509_CRL_METHOD *m);

/**
 * @brief Attach method-specific application data to a CRL for its X509_CRL_METHOD callbacks.
 * @param crl CRL whose method data pointer is replaced.
 * @param dat Opaque pointer retrieved later with X509_CRL_get_meth_data().
 */
void X509_CRL_set_meth_data(X509_CRL *crl, void *dat);
/**
 * @brief Return the method-specific application data previously set on a CRL.
 * @param crl CRL whose X509_CRL_METHOD data pointer is queried.
 * @return Opaque pointer last passed to X509_CRL_set_meth_data(), or NULL if unset.
 */
void *X509_CRL_get_meth_data(X509_CRL *crl);

/**
 * @brief Return a human-readable string for an X509_V_ERR_* verification error code.
 * @param n Error code such as from X509_STORE_CTX_get_error() or X509_verify_cert().
 * @return Static descriptive string; never NULL (unknown codes yield a generic message).
 */
const char *X509_verify_cert_error_string(long n);

/**
 * @brief Verify a certificate's signature with the issuer public key @p r.
 * @param a Certificate whose signature is verified.
 * @param r Public key expected to have signed @p a (typically the issuer key).
 * @return 1 if the signature is valid, 0 if invalid, or a negative value on error.
 */
int X509_verify(X509 *a, EVP_PKEY *r);
/**
 * @brief Test whether @p cert is self-issued, optionally verifying its signature.
 * @param cert Certificate to examine.
 * @param verify_signature Non-zero to verify the signature with the certificate's own public key; 0 to compare names only.
 * @return 1 if self-signed (and verified when requested), 0 if not, or -1 on error.
 */
/**
 * @brief Test whether @p cert is self-issued, optionally verifying its signature.
 * @param cert Certificate to examine.
 * @param verify_signature Non-zero to verify the signature with the certificate's own public key; 0 to compare names only.
 * @return 1 if self-signed (and verified when requested), 0 if not, or -1 on error.
 */
int X509_self_signed(X509 *cert, int verify_signature);

/**
 * @brief Verify a certificate request's signature with an explicit library context.
 * @param a Certificate signing request to verify.
 * @param r Public key expected to have signed @p a.
 * @param libctx Library context used when fetching algorithms, or NULL for the default.
 * @param propq Property query for algorithm fetches, or NULL.
 * @return 1 if the signature is valid, 0 if invalid, or a negative value on error.
 */
int X509_REQ_verify_ex(X509_REQ *a, EVP_PKEY *r, OSSL_LIB_CTX *libctx,
    const char *propq);
/**
 * @brief Verify a certificate request's signature with public key @p r.
 * @param a Certificate signing request whose signature is checked.
 * @param r Public key expected to have signed @p a.
 * @return 1 if the signature is valid, 0 if invalid, or a negative value on error.
 */
int X509_REQ_verify(X509_REQ *a, EVP_PKEY *r);
/**
 * @brief Verify a CRL's signature with the issuer public key @p r.
 * @param a Certificate revocation list whose signature is checked.
 * @param r Public key expected to have signed @p a.
 * @return 1 if the signature is valid, 0 if invalid, or a negative value on error.
 */
int X509_CRL_verify(X509_CRL *a, EVP_PKEY *r);
/**
 * @brief Verify the signature on a Netscape Signed Public Key and Challenge (SPKI) structure.
 * @param a SPKI structure whose signature is checked.
 * @param r Public key expected to have signed @p a.
 * @return 1 if the signature is valid, 0 if invalid, or a negative value on error.
 */
int NETSCAPE_SPKI_verify(NETSCAPE_SPKI *a, EVP_PKEY *r);

/**
 * @brief Decode a base64-encoded Netscape SPKI structure from a string.
 * @param str Base64 text of a SignedPublicKeyAndChallenge.
 * @param len Length of @p str in bytes, or -1 if @p str is NUL-terminated.
 * @return Newly allocated NETSCAPE_SPKI, or NULL on error; free with NETSCAPE_SPKI_free().
 */
NETSCAPE_SPKI *NETSCAPE_SPKI_b64_decode(const char *str, int len);
/**
 * @brief Base64-encode a Netscape Signed Public Key and Challenge structure.
 * @param x SPKI to encode.
 * @return Newly allocated Base64 string, or NULL on failure; free with OPENSSL_free().
 */
char *NETSCAPE_SPKI_b64_encode(NETSCAPE_SPKI *x);
/**
 * @brief Extract the public key from a Netscape SPKI structure.
 * @param x SPKI object whose SPKAC contains the public key.
 * @return Newly allocated EVP_PKEY, or NULL on error; free with EVP_PKEY_free().
 */
EVP_PKEY *NETSCAPE_SPKI_get_pubkey(NETSCAPE_SPKI *x);
/**
 * @brief Set the public key in a Netscape SPKI structure from @p pkey.
 * @param x SPKI whose SPKAC public-key field is replaced.
 * @param pkey Public key (or key pair) whose public component is encoded into @p x.
 * @return 1 on success, or 0 on failure.
 */
int NETSCAPE_SPKI_set_pubkey(NETSCAPE_SPKI *x, EVP_PKEY *pkey);

/**
 * @brief Print a human-readable representation of a Netscape signed public key and challenge.
 * @param out BIO that receives the textual dump.
 * @param spki SPKI structure to print.
 * @return 1 on success, or 0 on failure.
 */
/**
 * @brief Print a human-readable representation of a Netscape signed public key and challenge.
 * @param out BIO that receives the textual dump.
 * @param spki SPKI structure to print.
 * @return 1 on success, or 0 on failure.
 */
int NETSCAPE_SPKI_print(BIO *out, NETSCAPE_SPKI *spki);

/**
 * @brief Hex-dump an ASN.1 signature BIT/OCTET STRING to a BIO with indentation.
 * @param bp Destination BIO.
 * @param sig Signature bytes to dump.
 * @param indent Number of spaces prefixed to each output line.
 * @return 1 on success, or 0 on failure.
 */
int X509_signature_dump(BIO *bp, const ASN1_STRING *sig, int indent);
/**
 * @brief Print a signature algorithm and optional signature value to a BIO.
 * @param bp Destination BIO.
 * @param alg Signature algorithm identifier to print.
 * @param sig Signature bit string to dump, or NULL to print only the algorithm.
 * @return 1 on success, or 0 on failure.
 */
int X509_signature_print(BIO *bp, const X509_ALGOR *alg,
    const ASN1_STRING *sig);

/**
 * @brief Sign an X509 certificate with a private key and message digest.
 * @param x Certificate whose TBSCertificate is signed; version may be raised to v3 when extensions are present.
 * @param pkey Private key used to create the signature.
 * @param md Digest algorithm, or NULL to use the key type's default.
 * @return Number of bytes in the signature on success, or 0 on failure.
 */
int X509_sign(X509 *x, EVP_PKEY *pkey, const EVP_MD *md);
/**
 * @brief Sign certificate @p x using an already-initialized digest/signing context.
 * @param x Certificate whose signature is computed and stored.
 * @param ctx EVP_MD_CTX prepared for signing (digest + private key).
 * @return 1 on success, or 0 on failure.
 */
int X509_sign_ctx(X509 *x, EVP_MD_CTX *ctx);
/**
 * @brief Sign a certificate request with a private key and message digest.
 * @param x Certificate request that receives the signature.
 * @param pkey Private key used to sign.
 * @param md Message digest algorithm (for example EVP_sha256()), or NULL when implied by @p pkey.
 * @return 1 on success, or 0 on failure.
 */
int X509_REQ_sign(X509_REQ *x, EVP_PKEY *pkey, const EVP_MD *md);
/**
 * @brief Sign certificate request @p x using an already-initialized digest/signing context.
 * @param x Certificate request whose signature is computed and stored.
 * @param ctx EVP_MD_CTX prepared for signing (digest + private key).
 * @return 1 on success, or 0 on failure.
 */
int X509_REQ_sign_ctx(X509_REQ *x, EVP_MD_CTX *ctx);
/**
 * @brief Sign a certificate revocation list with a private key and digest.
 * @param x CRL whose TBSCertList is signed; signature fields are filled in.
 * @param pkey Private key used for signing.
 * @param md Message digest identifying the signature algorithm.
 * @return 1 on success, or 0 on failure.
 */
int X509_CRL_sign(X509_CRL *x, EVP_PKEY *pkey, const EVP_MD *md);
/**
 * @brief Sign a CRL using an initialized digest/signing context.
 * @param x CRL whose TBSCertList is signed; signature fields are filled in.
 * @param ctx Digest context already set up with the private key and algorithm parameters.
 * @return Size of the signature in bytes on success, or 0 on failure.
 */
int X509_CRL_sign_ctx(X509_CRL *x, EVP_MD_CTX *ctx);
/**
 * @brief Sign a Netscape SPKI with a private key and message digest.
 * @param x SPKI whose SPKAC payload is signed; signature fields are updated in place.
 * @param pkey Private key used to create the signature.
 * @param md Digest algorithm, or NULL to use the key type's default.
 * @return Number of bytes in the signature on success, or 0 on failure.
 */
int NETSCAPE_SPKI_sign(NETSCAPE_SPKI *x, EVP_PKEY *pkey, const EVP_MD *md);

/**
 * @brief Compute a digest of the DER-encoded public key of an X.509 certificate.
 * @param data Certificate whose SubjectPublicKeyInfo is digested.
 * @param type Digest algorithm such as EVP_sha1().
 * @param md Output buffer large enough for the digest (at least EVP_MAX_MD_SIZE).
 * @param len On success, set to the digest length in bytes; may be NULL.
 * @return 1 on success, or 0 on failure.
 */
int X509_pubkey_digest(const X509 *data, const EVP_MD *type,
    unsigned char *md, unsigned int *len);
/**
 * @brief Compute a message digest of the DER encoding of an X.509 certificate.
 * @param data Certificate to hash.
 * @param type Digest algorithm (for example EVP_sha256()).
 * @param md Output buffer that receives the digest (must be large enough for @p type).
 * @param len On entry unused; on success set to the digest length in bytes (may be NULL).
 * @return 1 on success, or 0 on failure.
 */
int X509_digest(const X509 *data, const EVP_MD *type,
    unsigned char *md, unsigned int *len);
/**
 * @brief Digest a certificate using its signature hash (or a documented fallback).
 * @param cert Certificate whose DER encoding is hashed.
 * @param md_used If non-NULL, receives the EVP_MD that was used (caller must EVP_MD_free it when non-NULL).
 * @param md_is_fallback If non-NULL, set to 1 when a fallback digest was chosen, else 0.
 * @return Newly allocated ASN1_OCTET_STRING holding the digest, or NULL on error.
 */
ASN1_OCTET_STRING *X509_digest_sig(const X509 *cert,
    EVP_MD **md_used, int *md_is_fallback);
/**
 * @brief Compute a digest of the DER encoding of an entire X.509 CRL.
 * @param data CRL to digest.
 * @param type Digest algorithm such as EVP_sha1().
 * @param md Output buffer large enough for the digest (at least EVP_MAX_MD_SIZE).
 * @param len On success, set to the digest length in bytes; may be NULL.
 * @return 1 on success, or 0 on failure.
 */
int X509_CRL_digest(const X509_CRL *data, const EVP_MD *type,
    unsigned char *md, unsigned int *len);
/**
 * @brief Digest the DER encoding of a certificate request with hash @p type.
 * @param data Certificate request to hash.
 * @param type Digest method to use.
 * @param md Buffer receiving the digest (at least EVP_MD_size(@p type) bytes).
 * @param len Receives the digest length in bytes.
 * @return 1 on success, or 0 on error.
 */
int X509_REQ_digest(const X509_REQ *data, const EVP_MD *type,
    unsigned char *md, unsigned int *len);
/**
 * @brief Compute a digest of the DER encoding of an X.509 Name (DN).
 * @param data Distinguished name to hash.
 * @param type Digest algorithm such as EVP_sha1().
 * @param md Output buffer large enough for the digest (at least EVP_MAX_MD_SIZE).
 * @param len On success, set to the digest length in bytes; may be NULL.
 * @return 1 on success, or 0 on failure.
 */
int X509_NAME_digest(const X509_NAME *data, const EVP_MD *type,
    unsigned char *md, unsigned int *len);

/**
 * @brief Download an X.509 certificate from @p url over HTTP(S).
 * @param url URL of the certificate resource.
 * @param bio Optional BIO used for the outbound connection, or NULL to create one.
 * @param rbio Optional separate read BIO for bidirectional setups, or NULL.
 * @param timeout Transfer timeout in seconds (0 uses the default).
 * @return Decoded X509 certificate, or NULL on error.
 */
X509 *X509_load_http(const char *url, BIO *bio, BIO *rbio, int timeout);
/**
 * @brief Load an X.509 CRL in ASN.1/DER form via HTTP from @p url.
 * @param url HTTP or HTTPS URL of the CRL.
 * @param bio Optional BIO used for the connection when @p rbio is NULL, or NULL for an internal BIO.
 * @param rbio Optional separate read BIO paired with @p bio, or NULL.
 * @param timeout Maximum seconds to wait, or 0 for no timeout / default behaviour.
 * @return Decoded X509_CRL, or NULL on error; free with X509_CRL_free.
 */
X509_CRL *X509_CRL_load_http(const char *url, BIO *bio, BIO *rbio, int timeout);
#ifndef OPENSSL_NO_DEPRECATED_3_0
#include <openssl/http.h> /* OSSL_HTTP_REQ_CTX_nbio_d2i */
#define X509_http_nbio(rctx, pcert) \
    OSSL_HTTP_REQ_CTX_nbio_d2i(rctx, pcert, ASN1_ITEM_rptr(X509))
#define X509_CRL_http_nbio(rctx, pcrl) \
    OSSL_HTTP_REQ_CTX_nbio_d2i(rctx, pcrl, ASN1_ITEM_rptr(X509_CRL))
#endif

