/**
 * @brief Set a PKCS#5 PBE algorithm OID and parameters into an existing X509_ALGOR.
 * @param algor AlgorithmIdentifier to update in place.
 * @param alg PBE algorithm NID (for example NID_pbeWithMD5AndDES_CBC).
 * @param iter PBKDF iteration count.
 * @param salt Optional salt bytes, or NULL to generate @p saltlen random bytes (0 uses a default length).
 * @param saltlen Salt length in bytes, or size to generate when @p salt is NULL.
 * @return 1 on success, or 0 on failure.
 */
int PKCS5_pbe_set0_algor(X509_ALGOR *algor, int alg, int iter,
    const unsigned char *salt, int saltlen);
/**
 * @brief Set a PBES1 AlgorithmIdentifier (OID, iteration count, and salt) with a library context.
 * @param algor Destination AlgorithmIdentifier updated in place.
 * @param alg PBE algorithm NID.
 * @param iter Iteration count for key derivation.
 * @param salt Salt octets, or NULL to generate a random salt of length @p saltlen (or a default when @p saltlen is 0).
 * @param saltlen Length of @p salt in bytes, or the length of salt to generate when @p salt is NULL.
 * @param libctx Library context for random salt generation, or NULL for the default.
 * @return 1 on success, or 0 on failure.
 */
int PKCS5_pbe_set0_algor_ex(X509_ALGOR *algor, int alg, int iter,
    const unsigned char *salt, int saltlen,
    OSSL_LIB_CTX *libctx);

/**
 * @brief Build an AlgorithmIdentifier for PKCS#5 PBE with @p alg, @p iter, and @p salt.
 * @param alg PBE algorithm NID.
 * @param iter Iteration count.
 * @param salt Salt bytes, or NULL to generate a random salt of @p saltlen.
 * @param saltlen Salt length in bytes.
 * @return New X509_ALGOR, or NULL on error; free with X509_ALGOR_free().
 */
X509_ALGOR *PKCS5_pbe_set(int alg, int iter,
    const unsigned char *salt, int saltlen);
/**
 * @brief Build a PKCS#5 PBE AlgorithmIdentifier using an explicit library context.
 * @param alg PBE algorithm NID.
 * @param iter Iteration count.
 * @param salt Salt bytes, or NULL to generate a random salt of @p saltlen.
 * @param saltlen Salt length in bytes.
 * @param libctx Library context used when generating a random salt, or NULL for the default.
 * @return New X509_ALGOR, or NULL on error; free with X509_ALGOR_free().
 */
X509_ALGOR *PKCS5_pbe_set_ex(int alg, int iter,
    const unsigned char *salt, int saltlen,
    OSSL_LIB_CTX *libctx);

/**
 * @brief Build a PKCS#5 PBES2 AlgorithmIdentifier for @p cipher with PBKDF2.
 * @param cipher Content-encryption cipher for the PBES2 encryption scheme.
 * @param iter PBKDF2 iteration count; <=0 selects the default.
 * @param salt Optional salt bytes; NULL generates a random salt of @p saltlen (default 16 if 0).
 * @param saltlen Salt length in bytes when @p salt is NULL / length of @p salt.
 * @return New X509_ALGOR encoding PBES2 parameters, or NULL on error; free with X509_ALGOR_free().
 */
X509_ALGOR *PKCS5_pbe2_set(const EVP_CIPHER *cipher, int iter,
    unsigned char *salt, int saltlen);
/**
 * @brief Build a PKCS#5 PBES2 AlgorithmIdentifier for @p cipher with optional IV and PBKDF2 PRF.
 * @param cipher Cipher that defines the encryption scheme.
 * @param iter PBKDF2 iteration count.
 * @param salt Salt bytes, or NULL as implemented.
 * @param saltlen Length of @p salt in bytes.
 * @param aiv Explicit IV bytes, or NULL to generate one.
 * @param prf_nid NID of the PBKDF2 PRF, or 0 for the default.
 * @return Newly allocated X509_ALGOR, or NULL on error.
 */
X509_ALGOR *PKCS5_pbe2_set_iv(const EVP_CIPHER *cipher, int iter,
    unsigned char *salt, int saltlen,
    unsigned char *aiv, int prf_nid);
/**
 * @brief Build a PBES2 AlgorithmIdentifier with explicit IV and library context.
 * @param cipher Content-encryption cipher for the PBES2 encryption scheme.
 * @param iter PBKDF2 iteration count; <=0 selects the default.
 * @param salt Optional salt bytes; NULL generates a random salt of @p saltlen.
 * @param saltlen Salt length in bytes when @p salt is NULL / length of @p salt.
 * @param aiv Optional IV bytes for @p cipher; NULL generates a random IV.
 * @param prf_nid PBKDF2 PRF NID (for example NID_hmacWithSHA256), or -1 for the default.
 * @param libctx Library context for random/algorithm fetches, or NULL for the default.
 * @return New X509_ALGOR encoding PBES2 parameters, or NULL on error.
 */
X509_ALGOR *PKCS5_pbe2_set_iv_ex(const EVP_CIPHER *cipher, int iter,
    unsigned char *salt, int saltlen,
    unsigned char *aiv, int prf_nid,
    OSSL_LIB_CTX *libctx);

#ifndef OPENSSL_NO_SCRYPT
/**
 * @brief Build a PBES2 AlgorithmIdentifier that derives the key with scrypt.
 * @param cipher Content-encryption cipher wrapped by PBES2.
 * @param salt Salt octets for scrypt, or NULL to generate a default-length salt.
 * @param saltlen Length of @p salt in bytes; ignored when @p salt is NULL.
 * @param aiv Optional IV octets for @p cipher, or NULL to generate a suitable IV.
 * @param N scrypt CPU/memory cost parameter.
 * @param r scrypt block size parameter.
 * @param p scrypt parallelization parameter.
 * @return New X509_ALGOR describing the PBES2/scrypt parameters, or NULL on error.
 */
X509_ALGOR *PKCS5_pbe2_set_scrypt(const EVP_CIPHER *cipher,
    const unsigned char *salt, int saltlen,
    unsigned char *aiv, uint64_t N, uint64_t r,
    uint64_t p);
#endif

/**
 * @brief Build an X509_ALGOR describing PBKDF2 key-derivation parameters.
 * @param iter PBKDF2 iteration count.
 * @param salt Salt bytes, or NULL to generate/omit as implemented.
 * @param saltlen Length of @p salt in bytes.
 * @param prf_nid NID of the PRF digest (e.g. NID_hmacWithSHA256), or 0 for the default.
 * @param keylen Derived key length in bytes, or 0 if omitted from the parameters.
 * @return Newly allocated X509_ALGOR, or NULL on error.
 */
X509_ALGOR *PKCS5_pbkdf2_set(int iter, unsigned char *salt, int saltlen,
    int prf_nid, int keylen);
/**
 * @brief Build an X509_ALGOR describing PBKDF2 parameters (library-context aware).
 * @param iter PBKDF2 iteration count.
 * @param salt Salt octets; may be NULL to generate a random salt of @p saltlen.
 * @param saltlen Salt length in bytes.
 * @param prf_nid NID of the PRF digest (for example NID_hmacWithSHA256); <= 0 selects the default.
 * @param keylen Derived key length in bytes to encode in the parameters; <= 0 omits it.
 * @param libctx Library context used for any random salt generation; NULL uses the default.
 * @return New X509_ALGOR on success, or NULL on failure.
 */
X509_ALGOR *PKCS5_pbkdf2_set_ex(int iter, unsigned char *salt, int saltlen,
    int prf_nid, int keylen,
    OSSL_LIB_CTX *libctx);

